report_format.md
# /app/report.json

```json
{"culprit": "H-2",
 "effect": {"lo": 1.31, "hi": 1.58}}
```

* `culprit` (string) - one change id.
* `effect.lo`, `effect.hi` (numbers) - external-suite points gained by rolling back the change you named in
  `culprit`.  Graded against that change, not against the correct one, so a wrong culprit costs you one item
  and not two.  `hi - lo` must be <= 0.45.

Nothing else in the file is read.  There is no partial credit inside an item.
{
 "ops": {
  "train": {
   "args": {
    "revert": "list of change ids to roll back in the training pipeline"
   },
   "cost": "8 credits",
   "returns": "a checkpoint id; deterministic given the reversion set"
  },
  "score": {
   "args": {
    "ckpt": "'release', 'previous', or an id from `train`",
    "harness": "optional: list of change ids rolled back in the in-house harness.  If omitted, the harness is built from the checkpoint's own manifest (the same changes rolled back as in its training)",
    "n": "eval units, 1..8"
   },
   "cost": "n x 1 credits",
   "noise": "+-0.057 points per unit",
   "returns": "mean in-house score over n units, and the per-unit values"
  },
  "ext": {
   "args": {
    "ckpt": "'release', 'previous', or an id from `train`",
    "n": "eval units, 1..8"
   },
   "cost": "n x 4 credits",
   "noise": "+-0.30 points per unit",
   "returns": "mean external-suite score over n units, and the per-unit values"
  }
 },
 "changes_in_release": [
  "H-1",
  "H-2",
  "H-3",
  "H-4",
  "H-5"
 ],
 "archived_checkpoints": [
  "release",
  "previous"
 ],
 "deliverable": "/app/report.json (see /app/docs/report_format.md)",
 "budget_total": 120.0,
 "budget_left": 120.0
}
{
 "budget_total": 120.0,
 "budget_spent": 0.0,
 "budget_left": 120.0,
 "n_calls": 0
}

